-- Samme bilde for alle Nishman-puddervariantene (Fixit har bare ett bilde).
update products set content_note = coalesce(content_note || ' ', '') || 'Bildet er felles for alle duftvariantene.'
 where slug like 'nishman-hair-styling-powder-%' and coalesce(content_note, '') not like '%felles for alle duft%';

notify pgrst, 'reload schema';

do $$
declare n int; m int;
begin
  select count(*) into n from products where slug is not null and is_gift_card = false and (coalesce(array_length(images, 1), 0) > 0 or image_url is not null);
  select count(*) into m from products where slug is not null and is_gift_card = false and coalesce(array_length(images, 1), 0) = 0 and image_url is null;
  raise notice 'Produkter med bilde: %, uten bilde: %', n, m;
end $$;

commit;
